def skew(v):
 x,y,z=v;return np.array([[0,-z,y],[z,0,-x],[-y,x,0]])
def rot(a,t):
 a=a/np.linalg.norm(a);K=skew(a);return np.eye(3)+np.sin(t)*K+(1-np.cos(t))*K@K
def rootrot(g):
 p=np.arctan2(g[0],np.hypot(g[1],g[2]));roll=-np.arctan2(g[1],-g[2]);return rot(np.array([0,1,0]),p)@rot(np.array([1,0,0]),roll)
def fk(q,R=np.eye(3)):
 transforms={};co=[];jointp=np.zeros((19,3));axes=np.zeros((19,3));children=[[] for _ in range(19)];anc={}
 for li,name in enumerate(ln):
  pt=transforms[par[li]] if par[li] else np.eye(4);anc[name]=anc.get(par[li],[]).copy()
  if name in ji:
   j=ji[name];p=jp0[j];rv=rot(ax0[j],q[j]);tt=np.eye(4);tt[:3,:3]=rv;tt[:3,3]=p-rv@p;T=pt@tt;jointp[j]=R@(pt@np.r_[p,1])[:3];axes[j]=R@pt[:3,:3]@ax0[j];anc[name].append(j)
  else:T=pt
  transforms[name]=T;c=R@(T@np.r_[com0[li],1])[:3];co.append(c)
  for j in anc[name]:children[j].append(li)
 co=np.array(co);com=(co*mass[:,None]).sum(0)/total;feet=[];verts=[];ank=[]
 for side in ['left','right']:
  name=side+'_ankle_link';bb=np.array(footboxes[name]);corners=np.array([[x,y,z,1] for x in bb[:,0] for y in bb[:,1] for z in bb[:,2]]);vs=(R@(transforms[name]@corners.T)[:3]).T;verts.append(vs);feet.append(vs[vs[:,2]<vs[:,2].min()+.006].mean(0));ank.append(jointp[4 if side=='left' else 9])
 return dict(com=com,feet=np.array(feet),ank=np.array(ank),verts=np.array(verts),jointp=jointp,axes=axes,co=co,children=children)
def compensation(q,R,forces,cops):
 k=fk(q,R);tau=np.zeros(19);gravity=np.array([0,0,-9.81])
