  torque=sum((np.cross(k['co'][li]-k['jointp'][j],gravity*mass[li]) for li in k['children'][j]),np.zeros(3))
  for side in range(2):
   if j in list(range(5*side,5*side+5)):torque+=np.cross(cops[side]-k['jointp'][j],forces[side])
  tau[j]=-k['axes'][j]@torque
 return tau
